 if(!Number.isSafeInteger(limit)||limit<1000)throw Error('No further funding fits the current milestone, monthly cap and protected budget.');
 const current=maximum?null:ipsNumber(form.value.amount,'Custom research contribution',{max:v.capabilityCap});
 if(!maximum&&current>=limit)throw Error('Amount is at or above the '+ipsMoney(limit)+' limit.');
 const amount=maximum?limit:E.fundingStep(v.me,without,branch,current+50000,v),next=ipsCopy(draft);
 if(!Number.isSafeInteger(amount)||amount<1000||!maximum&&amount<=current)throw Error('No additional research contribution is available.');
